// Réception d'une mise à jour Telegram : filtre l'expéditeur, évite les doublons, retrouve la conversation en cours
const ALLOWED = 8848139246;
const upd = $input.first().json.body || {};
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || [];
sd.sessions = sd.sessions || {};

const msg = upd.message, cb = upd.callback_query;
const from = (msg && msg.from) || (cb && cb.from) || {};
const chat = (msg && msg.chat) || (cb && cb.message && cb.message.chat) || {};

// seul le compte de Valentin est autorisé : tout autre expéditeur est ignoré sans réponse
if (Number(from.id) !== ALLOWED || Number(chat.id) !== ALLOWED) return [{ json: { route: 'ignore' } }];

// une même mise à jour n'est jamais traitée deux fois
if (upd.update_id !== undefined) {
  if (sd.seen.includes(upd.update_id)) return [{ json: { route: 'ignore' } }];
  sd.seen.push(upd.update_id);
  if (sd.seen.length > 100) sd.seen = sd.seen.slice(-100);
}

const key = String(chat.id);
let s = sd.sessions[key];
if (s && Date.now() - (s.updated || 0) > 45 * 60 * 1000) { delete sd.sessions[key]; s = undefined; } // conversation expirée après 45 min

let route = 'message', text = '', pick = 0;
if (cb) route = 'callback';
else if (msg && msg.text && s && s.state === 'reply_pick' && s.mail_candidates && /^\s*[1-9]\s*$/.test(msg.text)) { route = 'reply_choose'; pick = Number(msg.text.trim()); }
else if (msg && msg.text) route = 'claude';
else text = "Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.";

return [{ json: {
  route, text, pick, chat_id: chat.id, update_id: upd.update_id,
  user_text: msg ? (msg.text || '') : '',
  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',
  session: s || null,
} }];

// Valentin a répondu par un numéro : on retient le mail choisi dans la liste
const j = $('Normaliser la mise à jour').first().json;
const sd = $getWorkflowStaticData('global');
const key = String(j.chat_id);
const s = (sd.sessions || {})[key];
const say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];
const c = s && s.mail_candidates && s.mail_candidates[Number(j.pick) - 1];
if (!c) return say(`Ce numéro ne correspond à aucun mail de la liste. Répondez par un numéro de 1 à ${(s && s.mail_candidates || []).length || 1}, ou reformulez votre demande.`);
sd.sessions[key] = { state: 'reply_pending', reply_to: c, reply_pending: true, instructions: s.instructions || '', updated: Date.now() };
return [{ json: { chat_id: j.chat_id, next: 'redraft', user_text: s.instructions || 'Rédige une réponse appropriée à ce mail.', session: sd.sessions[key] } }];

// Traite un clic sur un bouton : annulation ou envoi (préparation du message à expédier)
const j = $('Normaliser la mise à jour').first().json;
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const key = String(j.chat_id);
const s = sd.sessions[key];
const say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];

if (j.cb_data === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }
// bouton « Répondre » d'une alerte urgente : on retrouve le mail par sa boîte et son identifiant
const rm = /^rep:(v|c):(\d+)$/.exec(j.cb_data || '');
if (rm) return [{ json: { chat_id: j.chat_id, next: 'find_uid', box_name: rm[1] === 'v' ? 'v.caufriez' : 'contact', uid: rm[2] } }];
const m = /^send:(v|c)$/.exec(j.cb_data || '');
if (!m) return say('Action inconnue.');
if (!s || s.state !== 'ready' || !s.draft || !s.draft.to_address || !s.draft.body) {
  return say("Ce brouillon n'est plus en attente (déjà envoyé, annulé ou expiré). Redites-moi ce que vous voulez envoyer.");
}
const BOX = {
  v: { from: 'v.caufriez@ebanista.fr', fromName: 'Valentin Caufriez', signature: 'Valentin Caufriez', label: 'v.caufriez@ebanista.fr' },
  c: { from: 'contact@ebanista.fr', fromName: 'Ebanista', signature: "L'équipe Ebanista", label: 'contact@ebanista.fr' },
}[m[1]];
s.state = 'sending'; s.updated = Date.now();
const d = s.draft;
let text = `${d.body.replace(/\s+$/, '')}\n\n${BOX.signature}`;
const r = s.reply_to;
if (r) {
  const when = r.recu_le ? new Date(r.recu_le).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';
  const quoted = String(r.extrait || '').replace(/\r/g, '').trim().split('\n').map(l => '> ' + l).join('\n');
  text += `\n\n\nLe ${when}, ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}> a écrit :\n${quoted}\n`;
}
return [{ json: {
  chat_id: j.chat_id, next: 'send', box: m[1], label: BOX.label,
  from: BOX.from, fromName: BOX.fromName,
  from_header: `${BOX.fromName} <${BOX.from}>`,
  to: d.to_address, to_name: d.to_name || '', subject: d.subject || '(sans objet)',
  in_reply_to: r && r.message_id ? r.message_id : '',
  text,
} }];

// Le mail de l'alerte est retrouvé : on prépare la conversation et on demande à Valentin ce qu'il veut répondre
const j = $('Normaliser la mise à jour').first().json;
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const key = String(j.chat_id);
const r = ($input.first().json.data || [])[0];
const say = (text) => [{ json: { chat_id: j.chat_id, text } }];
if (!r) return say("Je n'ai pas retrouvé ce mail dans le registre (il date peut-être de plus de 45 jours). Dites-moi à quel mail répondre, par exemple « réponds au mail de … ».");
const keep = { boite: r.boite, recu_le: r.recu_le, from_address: r.from_address, from_name: r.from_name, subject: r.subject, message_id: r.message_id, extrait: r.extrait, resume: r.resume };
sd.sessions[key] = { state: 'reply_pending', reply_to: keep, reply_pending: true, instructions: '', updated: Date.now() };
const when = r.recu_le ? new Date(r.recu_le).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
return say(`↩️ Réponse au mail « ${(r.subject || '').slice(0, 80)} » de ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}> (reçu le ${when} sur ${r.boite}).\n\nQue voulez-vous répondre ? Dites-le-moi en quelques mots, ou écrivez « propose une réponse » et je prépare une réponse adaptée.`);

// Confirme l'envoi à Valentin et clôt la conversation
const t = $('Traiter le bouton').first().json;
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
delete sd.sessions[String(t.chat_id)];
let copyOk = true;
try {
  const r = $input.first().json;
  if (!r || r.error || r.deleted === false) copyOk = false;
} catch (e) { copyOk = false; }
return [{ json: { chat_id: t.chat_id, text: `✅ Mail envoyé depuis ${t.label}\nÀ : ${t.to}\nObjet : ${t.subject}` + (copyOk ? '\nUne copie est enregistrée dans Envoyés.' : "\n⚠️ La copie dans Envoyés n'a pas pu être enregistrée.") } }];

// L'envoi a échoué : on remet le brouillon en attente pour pouvoir réessayer
const t = $('Traiter le bouton').first().json;
const sd = $getWorkflowStaticData('global');
const s = (sd.sessions || {})[String(t.chat_id)];
if (s) { s.state = 'ready'; s.updated = Date.now(); }
let why = '';
try { why = String($input.first().json.error && ($input.first().json.error.message || $input.first().json.error) || '').slice(0, 200); } catch (e) {}
return [{ json: { chat_id: t.chat_id, text: `❌ L'envoi depuis ${t.label} a échoué${why ? ' : ' + why : ''}.\nLe brouillon est conservé : vous pouvez réessayer avec le même bouton ou choisir l'autre boîte.` } }];

// Compose la copie du mail envoyé (RFC822) pour le dossier Envoyés de la boîte
const t = $('Traiter le bouton').first().json;
const info = $input.first().json;
const CRLF = '\r\n';
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const isAscii = (s) => /^[\x20-\x7e]*$/.test(s);
const encodeHeader = (s) => {
  if (isAscii(s)) return s;
  const chars = Array.from(s), parts = [];
  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);
  return parts.join(CRLF + ' ');
};
const name = (n) => !n ? '' : (!isAscii(n) ? `=?UTF-8?B?${b64(n)}?=` : (/[^\w .'-]/.test(n) ? `"${n.replace(/(["\\])/g, '\\$1')}"` : n));
const msgId = info.messageId || `<copie-${Date.now()}@ebanista.fr>`;
const headers = [
  `From: ${name(t.fromName)} <${t.from}>`,
  `To: ${t.to_name ? name(t.to_name) + ' ' : ''}<${t.to}>`,
  `Subject: ${encodeHeader(t.subject)}`,
  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,
  `Message-ID: ${msgId}`,
  ...(t.in_reply_to ? [`In-Reply-To: ${t.in_reply_to}`, `References: ${t.in_reply_to}`] : []),
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
];
const body = b64(t.text.replace(/\r?\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);
return [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];

// Compose la copie du mail envoyé (RFC822) pour le dossier Envoyés de la boîte
const t = $('Traiter le bouton').first().json;
const info = $input.first().json;
const CRLF = '\r\n';
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const isAscii = (s) => /^[\x20-\x7e]*$/.test(s);
const encodeHeader = (s) => {
  if (isAscii(s)) return s;
  const chars = Array.from(s), parts = [];
  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);
  return parts.join(CRLF + ' ');
};
const name = (n) => !n ? '' : (!isAscii(n) ? `=?UTF-8?B?${b64(n)}?=` : (/[^\w .'-]/.test(n) ? `"${n.replace(/(["\\])/g, '\\$1')}"` : n));
const msgId = info.messageId || `<copie-${Date.now()}@ebanista.fr>`;
const headers = [
  `From: ${name(t.fromName)} <${t.from}>`,
  `To: ${t.to_name ? name(t.to_name) + ' ' : ''}<${t.to}>`,
  `Subject: ${encodeHeader(t.subject)}`,
  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,
  `Message-ID: ${msgId}`,
  ...(t.in_reply_to ? [`In-Reply-To: ${t.in_reply_to}`, `References: ${t.in_reply_to}`] : []),
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
];
const body = b64(t.text.replace(/\r?\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);
return [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];

// Construit le message envoyé à Claude : demande de Valentin + brouillon en cours + adresses proposées + éventuel mail reçu auquel répondre
const j = $input.first().json;
const s = j.session;
const parts = ['MESSAGE DE VALENTIN :', j.user_text];
if (s && s.reply_to) {
  const r = s.reply_to;
  parts.push('', 'MAIL REÇU AUQUEL TU RÉPONDS :',
    `De : ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}>`,
    `Objet : ${r.subject}`, `Reçu le : ${r.recu_le}`, `Boîte de réception : ${r.boite}`,
    'Contenu :', r.extrait || '(vide)');
  if (r.boite === 'contact') {
    parts.push('', "STYLE POUR CETTE BOÎTE (administrative) : vouvoiement soigné, phrases complètes et courtoises, \"Merci d'avance pour votre retour.\" avant la formule de fin (\"Cordialement,\"), aucune familiarité. Écris au nom de l'entreprise (« nous »), pas à la première personne du singulier.");
  }
}
if (s && s.draft && s.draft.body) {
  const d = s.draft;
  parts.push('', 'BROUILLON EN COURS :', `À : ${d.to_name || ''} <${d.to_address || 'adresse inconnue'}>`, `Objet : ${d.subject || ''}`, 'Corps :', d.body);
}
if (s && s.candidates && s.candidates.length) {
  parts.push('', 'ADRESSES PROPOSÉES POUR LE DESTINATAIRE (il peut répondre par un numéro) :');
  s.candidates.forEach((c, i) => parts.push(`${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`));
}
return [{ json: { ...j, prompt: parts.join('\n') } }];

// Applique la réponse de Claude à la conversation (brouillon, réponse à un mail, annulation, question) et décide de la suite
const j = $('Normaliser la mise à jour').first().json;
const raw = String($input.first().json.text || '');
let out = null;
try { out = JSON.parse(raw.match(/\{[\s\S]*\}/)[0]); } catch (e) { out = null; }

const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const key = String(j.chat_id);
const prev = sd.sessions[key];
const say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];
const reSubject = (s) => 'Re: ' + String(s || '').replace(/^\s*((re|ré)\s*:\s*)+/i, '').trim();

if (!out) return say("Je n'ai pas bien compris. Pouvez-vous reformuler votre demande ?");
if (out.intent === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }
if (out.intent === 'other') return say(out.reply || "Dites-moi à qui écrire, le sujet et ce qu'il faut dire (ou « réponds au mail de … »), et je prépare le mail.");

// demande de réponse à un mail déjà reçu : on retrouve d'abord le mail dans le registre
if (out.intent === 'reply') {
  sd.sessions[key] = { state: 'reply_search', find: out.find || {}, instructions: out.instructions || '', updated: Date.now() };
  return [{ json: { chat_id: j.chat_id, next: 'find' } }];
}

const okMail = (a) => (typeof a === 'string' && /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(a.trim())) ? a.trim() : null;
const d = (prev && prev.draft) || {};

// réponse à un mail reçu (première rédaction, ou révision d'un brouillon de réponse)
const replyTo = prev && prev.reply_to;
if (replyTo && (prev.reply_pending || (out.intent === 'revise' && prev.draft))) {
  const body = out.body || d.body || null;
  const nd = { to_name: replyTo.from_name || null, to_address: replyTo.from_address, subject: reSubject(replyTo.subject), body };
  sd.sessions[key] = { state: 'draft', draft: nd, reply_to: replyTo, candidates: null, updated: Date.now() };
  if (!body) return say(out.reply || 'Que voulez-vous répondre ?');
  return [{ json: { chat_id: j.chat_id, next: 'decide', lookup_name: '' } }];
}

let nd;
if (out.intent === 'revise' && prev && prev.draft) {
  nd = {
    to_name: out.to_name || d.to_name || null,
    to_address: okMail(out.to_address) || d.to_address || null,
    subject: out.subject || d.subject || null,
    body: out.body || d.body || null,
  };
} else {
  nd = { to_name: out.to_name || null, to_address: okMail(out.to_address), subject: out.subject || null, body: out.body || null };
}
sd.sessions[key] = { state: 'draft', draft: nd, candidates: null, updated: Date.now() };

if (!nd.body) return say(out.reply || 'Que voulez-vous dire dans ce mail ?');
const needLookup = !nd.to_address && !!nd.to_name;
return [{ json: { chat_id: j.chat_id, next: needLookup ? 'lookup' : 'decide', lookup_name: nd.to_name || '' } }];

// Regroupe en un seul élément les résultats de la recherche dans les Envoyés de v.caufriez@
const found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);
return [{ json: { found } }];

// Retrouve l'adresse du destinataire à partir de son nom, dans les dossiers Envoyés des deux boîtes
const ctx = $('Appliquer la réponse de Claude').first().json;
const j = $('Normaliser la mise à jour').first().json;
const sd = $getWorkflowStaticData('global');
const key = String(j.chat_id);
const s = sd.sessions[key];
const strip = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const tokens = strip(ctx.lookup_name).split(/[^a-z0-9]+/).filter(t => t.length >= 2);

const first = ($('Regrouper les résultats v.caufriez').first().json.found) || [];
const second = $input.all().map(i => i.json).filter(x => x && x.envelope && !x.error);
const MINE = ['v.caufriez@ebanista.fr', 'contact@ebanista.fr', 'comptabilite@ebanista.fr'];
const tally = {};
for (const m of [...first, ...second]) {
  for (const t of ((m.envelope && m.envelope.to) || [])) {
    const addr = String(t.address || '').toLowerCase();
    if (!addr || MINE.includes(addr)) continue;
    const hay = strip((t.name || '') + ' ' + addr);
    if (tokens.length && !tokens.every(tok => hay.includes(tok))) continue;
    const e = tally[addr] || (tally[addr] = { address: addr, name: t.name || '', count: 0 });
    e.count++;
    if (!e.name && t.name) e.name = t.name;
  }
}
const list = Object.values(tally).sort((a, b) => b.count - a.count);
if (s) {
  if (list.length === 1 || (list.length > 1 && list[0].count >= 2 * list[1].count && list[0].count >= 2)) {
    s.draft.to_address = list[0].address;
    if (!s.draft.to_name && list[0].name) s.draft.to_name = list[0].name;
  } else if (list.length > 1) {
    s.candidates = list.slice(0, 5).map(c => ({ name: c.name, address: c.address }));
  }
  s.updated = Date.now();
}
return [{ json: { chat_id: j.chat_id } }];

// Décide ce qu'il faut répondre à Valentin : question sur l'adresse, informations manquantes, ou aperçu avec boutons
const j = $('Normaliser la mise à jour').first().json;
const sd = $getWorkflowStaticData('global');
const key = String(j.chat_id);
const s = sd.sessions[key];
const out = (text, preview = false) => {
  const rec = s && s.reply_to ? s.reply_to.boite : '';
  const tag = ' (boîte du mail reçu)';
  return [{ json: { chat_id: j.chat_id, text, preview,
    label_v: '✉️ Envoyer depuis v.caufriez@ebanista.fr' + (rec === 'v.caufriez' ? tag : ''),
    label_c: '✉️ Envoyer depuis contact@ebanista.fr' + (rec === 'contact' ? tag : '') } }];
};
if (!s || !s.draft) return out("Je n'ai plus de brouillon en cours. Redites-moi à qui écrire et ce qu'il faut dire.");
const d = s.draft;

if (s.candidates && s.candidates.length) {
  s.state = 'awaiting_address'; s.updated = Date.now();
  const lines = s.candidates.map((c, i) => `${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`).join('\n');
  return out(`Plusieurs adresses possibles pour « ${d.to_name || 'ce destinataire'} » :\n${lines}\n\nRépondez par le numéro, ou donnez-moi directement l'adresse.`);
}
if (!d.to_address) {
  s.state = 'awaiting_address'; s.updated = Date.now();
  return out(`Je n'ai pas trouvé l'adresse e-mail de ${d.to_name || 'ce destinataire'}. Pouvez-vous me la donner ?`);
}
const missing = (d.body.match(/\[À COMPLÉTER[^\]]*\]/g) || []);
const r = s.reply_to;
const when = r && r.recu_le ? new Date(r.recu_le).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
const head = r ? `↩️ Réponse au mail « ${(r.subject || '').slice(0, 80)} » reçu le ${when} sur ${r.boite}\n\n` : '';
const draftText = `À : ${d.to_name ? d.to_name + ' ' : ''}<${d.to_address}>\nObjet : ${d.subject || '(sans objet)'}\n\n${d.body}`;
if (missing.length) {
  s.state = 'awaiting_info'; s.updated = Date.now();
  return out(`Il manque des informations avant de pouvoir envoyer :\n${missing.map(m => '• ' + m).join('\n')}\n\nPrécisez-les-moi et je mets le brouillon à jour.\n\n— Brouillon actuel —\n${head}${draftText}`);
}
s.state = 'ready'; s.updated = Date.now();
return out(`✉️ Brouillon prêt\n\n${head}${draftText}\n\n(La signature est ajoutée selon la boîte choisie${r ? ', et le mail d\'origine est cité en dessous' : ''}.)\nChoisissez la boîte d'envoi, ou dites-moi quoi modifier.`, true);

// Retrouve dans le registre le mail reçu auquel Valentin veut répondre
const j = $('Normaliser la mise à jour').first().json;
const sd = $getWorkflowStaticData('global');
const key = String(j.chat_id);
const s = (sd.sessions || {})[key];
const say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];
if (!s || s.state !== 'reply_search') return say("Je n'ai plus de demande en cours. Redites-moi à quel mail répondre.");

const rows = ($input.first().json.data || []).filter(r => r && r.from_address);
const f = s.find || {};
const strip = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const toks = (t) => strip(t).split(/[^a-z0-9]+/).filter(x => x.length >= 2);
const st = toks(f.sender), jt = toks(f.subject);
const bx = strip(f.box || '');
const boxOk = (r) => !bx || (bx.includes('contact') ? r.boite === 'contact' : (bx.includes('caufriez') || bx.includes('valentin')) ? r.boite === 'v.caufriez' : true);

let list = rows.filter(r => {
  if (!boxOk(r)) return false;
  const who = strip((r.from_name || '') + ' ' + r.from_address);
  if (st.length && !st.every(t => who.includes(t))) return false;
  return true;
});
if (jt.length) {
  const what = (r) => strip((r.subject || '') + ' ' + (r.resume || ''));
  const strict = list.filter(r => jt.every(t => what(r).includes(t)));
  list = strict.length ? strict : list.filter(r => jt.some(t => what(r).includes(t)));
}
list.sort((a, b) => String(b.recu_le).localeCompare(String(a.recu_le)));
const top = list.slice(0, 5);

const keep = (r) => ({ boite: r.boite, recu_le: r.recu_le, from_address: r.from_address, from_name: r.from_name, subject: r.subject, message_id: r.message_id, extrait: r.extrait, resume: r.resume });
const fmt = (r) => {
  const d = r.recu_le ? new Date(r.recu_le).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
  return `${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}> — « ${(r.subject || '').slice(0, 70)} » — ${d} — boîte ${r.boite}`;
};

if (top.length === 0) {
  delete sd.sessions[key];
  return say("Je n'ai pas retrouvé de mail correspondant dans les 45 derniers jours (boîtes v.caufriez et contact). Précisez l'expéditeur ou un mot de l'objet.");
}
if (top.length > 1) {
  s.state = 'reply_pick'; s.mail_candidates = top.map(keep); s.updated = Date.now();
  return say(`Plusieurs mails correspondent :\n${top.map((r, i) => `${i + 1}) ${fmt(r)}`).join('\n')}\n\nRépondez par le numéro du mail auquel répondre.`);
}
const chosen = keep(top[0]);
sd.sessions[key] = { state: 'reply_pending', reply_to: chosen, reply_pending: true, instructions: s.instructions || '', updated: Date.now() };
return [{ json: { chat_id: j.chat_id, next: 'redraft', user_text: s.instructions || 'Rédige une réponse appropriée à ce mail.', session: sd.sessions[key] } }];

// Construit le message envoyé à Claude : demande de Valentin + brouillon en cours + adresses proposées + éventuel mail reçu auquel répondre
const j = $input.first().json;
const s = j.session;
const parts = ['MESSAGE DE VALENTIN :', j.user_text];
if (s && s.reply_to) {
  const r = s.reply_to;
  parts.push('', 'MAIL REÇU AUQUEL TU RÉPONDS :',
    `De : ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}>`,
    `Objet : ${r.subject}`, `Reçu le : ${r.recu_le}`, `Boîte de réception : ${r.boite}`,
    'Contenu :', r.extrait || '(vide)');
  if (r.boite === 'contact') {
    parts.push('', "STYLE POUR CETTE BOÎTE (administrative) : vouvoiement soigné, phrases complètes et courtoises, \"Merci d'avance pour votre retour.\" avant la formule de fin (\"Cordialement,\"), aucune familiarité. Écris au nom de l'entreprise (« nous »), pas à la première personne du singulier.");
  }
}
if (s && s.draft && s.draft.body) {
  const d = s.draft;
  parts.push('', 'BROUILLON EN COURS :', `À : ${d.to_name || ''} <${d.to_address || 'adresse inconnue'}>`, `Objet : ${d.subject || ''}`, 'Corps :', d.body);
}
if (s && s.candidates && s.candidates.length) {
  parts.push('', 'ADRESSES PROPOSÉES POUR LE DESTINATAIRE (il peut répondre par un numéro) :');
  s.candidates.forEach((c, i) => parts.push(`${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`));
}
return [{ json: { ...j, prompt: parts.join('\n') } }];

// Applique la réponse de Claude à la conversation (brouillon, réponse à un mail, annulation, question) et décide de la suite
const j = $('Normaliser la mise à jour').first().json;
const raw = String($input.first().json.text || '');
let out = null;
try { out = JSON.parse(raw.match(/\{[\s\S]*\}/)[0]); } catch (e) { out = null; }

const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const key = String(j.chat_id);
const prev = sd.sessions[key];
const say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];
const reSubject = (s) => 'Re: ' + String(s || '').replace(/^\s*((re|ré)\s*:\s*)+/i, '').trim();

if (!out) return say("Je n'ai pas bien compris. Pouvez-vous reformuler votre demande ?");
if (out.intent === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }
if (out.intent === 'other') return say(out.reply || "Dites-moi à qui écrire, le sujet et ce qu'il faut dire (ou « réponds au mail de … »), et je prépare le mail.");

// demande de réponse à un mail déjà reçu : on retrouve d'abord le mail dans le registre
if (out.intent === 'reply') {
  sd.sessions[key] = { state: 'reply_search', find: out.find || {}, instructions: out.instructions || '', updated: Date.now() };
  return [{ json: { chat_id: j.chat_id, next: 'find' } }];
}

const okMail = (a) => (typeof a === 'string' && /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(a.trim())) ? a.trim() : null;
const d = (prev && prev.draft) || {};

// réponse à un mail reçu (première rédaction, ou révision d'un brouillon de réponse)
const replyTo = prev && prev.reply_to;
if (replyTo && (prev.reply_pending || (out.intent === 'revise' && prev.draft))) {
  const body = out.body || d.body || null;
  const nd = { to_name: replyTo.from_name || null, to_address: replyTo.from_address, subject: reSubject(replyTo.subject), body };
  sd.sessions[key] = { state: 'draft', draft: nd, reply_to: replyTo, candidates: null, updated: Date.now() };
  if (!body) return say(out.reply || 'Que voulez-vous répondre ?');
  return [{ json: { chat_id: j.chat_id, next: 'decide', lookup_name: '' } }];
}

let nd;
if (out.intent === 'revise' && prev && prev.draft) {
  nd = {
    to_name: out.to_name || d.to_name || null,
    to_address: okMail(out.to_address) || d.to_address || null,
    subject: out.subject || d.subject || null,
    body: out.body || d.body || null,
  };
} else {
  nd = { to_name: out.to_name || null, to_address: okMail(out.to_address), subject: out.subject || null, body: out.body || null };
}
sd.sessions[key] = { state: 'draft', draft: nd, candidates: null, updated: Date.now() };

if (!nd.body) return say(out.reply || 'Que voulez-vous dire dans ce mail ?');
const needLookup = !nd.to_address && !!nd.to_name;
return [{ json: { chat_id: j.chat_id, next: needLookup ? 'lookup' : 'decide', lookup_name: nd.to_name || '' } }];
